import{_ as i,o as t,c as o,a2 as a}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse(`{"title":"Guida dell'amministratore","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/index.md","filePath":"admin-guide/README.md"}`),r={name:"admin-guide/index.md"};function n(d,e,l,s,c,u){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="guida-dell-amministratore" tabindex="-1">Guida dell&#39;amministratore <a class="header-anchor" href="#guida-dell-amministratore" aria-label="Permalink to &quot;Guida dell&#39;amministratore&quot;">​</a></h1><p>Per chi installa, configura e gestisce il <strong>Cloud Service</strong> (API, worker, Web UI incorporata), PostgreSQL, l&#39;archivio S3-compatibile e Keycloak. Il prodotto si chiama &quot;Clarae notanda&quot;; nei manifest e nei comandi compare come <code>clarae</code>.</p><table tabindex="0"><thead><tr><th>Argomento</th><th>Contenuto</th></tr></thead><tbody><tr><td><a href="./installazione.html">Installazione</a></td><td>Architettura, prerequisiti, Helm, compose di sviluppo, primo avvio e verifica.</td></tr><tr><td><a href="./keycloak.html">Keycloak</a></td><td>Realm, client, ruoli, service account con i ruoli minimi (ADR-0012), ruolo <code>clarae-admin</code>.</td></tr><tr><td><a href="./configurazione.html">Configurazione</a></td><td>Riferimento di <strong>tutte</strong> le variabili d&#39;ambiente (verificato da un test) e impostazioni runtime.</td></tr><tr><td><a href="./profili-quote-audit.html">Profili, quote, audit</a></td><td>Gruppi, config profile distribuiti ai client, limiti di archiviazione, registro di audit.</td></tr><tr><td><a href="./presenza.html">Presenza in tempo reale</a></td><td>Flag <code>features.presence</code>, WebSocket, Ingress e timeout, scala e limiti per replica.</td></tr><tr><td><a href="./backup-upgrade.html">Backup e upgrade</a></td><td>Cosa salvare, ripristino, aggiornamenti con migrazioni, rollback.</td></tr><tr><td><a href="./monitoraggio.html">Monitoraggio</a></td><td>Metriche Prometheus, dashboard Grafana, regole di alerting, log.</td></tr><tr><td><a href="./runbook.html">Runbook</a></td><td>Sintomo → verifica → rimedio: login, sync, quota, sospensioni, export, database, S3.</td></tr><tr><td><a href="./migrazione-clarae.html">Migrazione a Clarae notanda</a></td><td>Aggiornare dalla 1.x: nomi vecchi e nuovi, Compose, Helm, Keycloak, metriche, rollback.</td></tr></tbody></table><p>Documenti collegati: <code>docs/runbook/</code> (procedure operative dettagliate: backup e ripristino), <code>docs/security/</code> (progetto crittografico, ambito pen test, conservazione dei dati), <code>docs/release/</code> (versioni, distribuzione, segreti di firma), <code>docs/adr/README.md</code> (decisioni architetturali).</p><h2 id="cosa-non-fa-il-server-e-quindi-cosa-non-potete-fare-voi" tabindex="-1">Cosa non fa il server (e quindi cosa non potete fare voi) <a class="header-anchor" href="#cosa-non-fa-il-server-e-quindi-cosa-non-potete-fare-voi" aria-label="Permalink to &quot;Cosa non fa il server (e quindi cosa non potete fare voi)&quot;">​</a></h2><ul><li>Il server <strong>non interpreta mai il contenuto</strong> delle note: non cerca, non indicizza e non mostra il testo dei vault. L&#39;unione delle modifiche (merge) è sempre eseguita dai client. Attenzione: i blob dei vault <strong>condivisi</strong> (non E2EE) sono in chiaro sull&#39;archivio S3, quindi chi ha accesso diretto allo storage può leggerli (lo dichiara anche la procedura di collegamento al cloud nel client).</li><li>I <strong>vault privati</strong> sono cifrati end-to-end dal client: percorsi e contenuti sono opachi anche per l&#39;amministratore. Non esiste un &quot;reset password&quot; per la passphrase di un vault privato: se l&#39;utente perde passphrase <strong>e</strong> recovery key, i dati sono irrecuperabili. Per lo stesso motivo il server non può esportarli.</li><li>I <strong>gruppi</strong> esistono solo nel database del servizio (D-05): non vengono letti da Keycloak né da LDAP.</li></ul>',6)])])}const g=i(r,[["render",n]]);export{p as __pageData,g as default};
